function pickKnown(input: Record<string, unknown>, keys: readonly string[]): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const key of keys) {
    if (Object.hasOwn(input, key)) out[key] = input[key];
  }
  return out;
}

const body = JSON.parse('{"name":"Ada","email":"ada@example.com","role":"admin"}') as Record<string, unknown>;
console.log(JSON.stringify(pickKnown(body, ["name", "email", "phone"])));

