type Handler<in E> = (event: E) => void;

interface Channel<in out E> {
  readonly publish: (event: E) => void;
  readonly subscribe: (handler: Handler<E>) => () => void;
}

function createChannel<E>(): Channel<E> {
  const handlers = new Set<Handler<E>>();
  return {
    publish: (event) => {
      for (const handler of handlers) handler(event);
    },
    subscribe: (handler) => {
      handlers.add(handler);
      return () => {
        handlers.delete(handler);
      };
    },
  };
}

interface PaymentCaptured {
  readonly id: string;
}
const payments = createChannel<PaymentCaptured>();
const audit: Handler<{ readonly id: string }> = (event) => console.log(`audit: ${event.id}`);
const stopSms = payments.subscribe((event) => console.log(`sms: ${event.id}`));
payments.subscribe(audit);
payments.publish({ id: "PAY-88" });
stopSms();
payments.publish({ id: "PAY-90" });

