function deepFreeze<T>(value: T): T {
  if (typeof value === "object" && value !== null) {
    for (const child of Object.values(value)) deepFreeze(child);
    Object.freeze(value);
  }
  return value;
}

const settings = deepFreeze({ delivery: { lagosKobo: 100000 }, zones: ["Lagos"] });
console.log(Object.isFrozen(settings), Object.isFrozen(settings.delivery), Object.isFrozen(settings.zones));

