function readSetting(settings: Readonly<Record<string, unknown>>, path: string): unknown {
  let node: unknown = settings;
  for (const key of path.split(".")) {
    if (typeof node !== "object" || node === null || !Object.hasOwn(node, key)) return undefined;
    node = (node as Record<string, unknown>)[key];
  }
  return node;
}

const settings = { delivery: { zones: { lagos: 100000 } }, currency: "NGN" };
console.log(readSetting(settings, "delivery.zones.lagos"), readSetting(settings, "delivery.zone.lagos"), readSetting(settings, "currency.toString"));
